use WebCommander\Sdk\Resources\Email\Email;

$response = Email::sendEmail($client, [
    'recipients' => ['customer@example.com'], 'cc' => ['orders@example.com'],
    'subject' => 'Your order has shipped', 'htmlContent' => '<p>Your order is on its way.</p>',
    'contentType' => 'text/html',
]);

echo $response->map['status'], PHP_EOL;
echo 'accepted: ', implode(', ', $response->map['accepted']), PHP_EOL;
echo 'rejected: ', implode(', ', $response->map['rejected']), PHP_EOL;
